_CHECKS = [0]
_FAILED = []


def _set_manual_db(owner, path, value):
    """Test helper: writes the legacy manual-dB offset straight into the library row, the way an older version saved it; returns False when the library cannot key the file."""
    probe = getattr(owner, "probe_library", owner)
    content_key = probe.keys.resolve(path)
    if content_key is None:
        return False
    probe.library.upsert_fields(content_key, manual_gain_db=value)
    if hasattr(owner, "forget"):
        owner.forget(path)
    return True


def check(ok, label):
    """Records one check. A section function calls this many times; the section's test fails if any failed."""
    _CHECKS[0] += 1
    if not ok:
        _FAILED.append(label)


_check_result = check


class _CacheHub:
    """Test stand-in for the duration hub: answers lengths from a {path: {"duration": seconds}} dict the way the old probe cache did."""

    def __init__(self, cache):
        self.cache = cache
        self.estimates = {}

    def read(self, path):
        entry = self.cache.get(path) or self.cache.get(os.path.normpath(path))
        seconds = entry.get("duration") if isinstance(entry, dict) else None
        if seconds and seconds > 0:
            return seconds, media.DURATION_MEASURED
        estimate = self.estimates.get(os.path.normpath(path))
        if estimate:
            return estimate, media.DURATION_ESTIMATED
        return None, None

    def store_estimate(self, path, seconds, basis):
        """Keeps an estimate for a file with no measured length the way the real hub does; a file with an estimate keeps it."""
        if not seconds or seconds <= 0 or self.read(path)[1] == media.DURATION_MEASURED:
            return None
        return self.estimates.setdefault(os.path.normpath(path), int(round(seconds)))


def _install_cache_hub(cache, testcase=None):
    """Makes media read file lengths from the given dict; the section runner and the test case put the previous hub back afterwards."""
    previous = media.get_duration_hub()
    media.set_duration_hub(_CacheHub(cache))
    if testcase is not None:
        testcase.addCleanup(media.set_duration_hub, previous)
    return previous


class _SectionCase(unittest.TestCase):
    """A test whose body is a section function full of check() calls; the test fails with the first labels that failed."""

    def run_section(self, fn, *args):
        before = len(_FAILED)
        _hub_before = media.get_duration_hub()
        try:
            fn(*args)
        finally:
            media.set_duration_hub(_hub_before)
        failed = _FAILED[before:]
        if failed:
            shown = "\n  ".join(str(label) for label in failed[:20])
            more = "" if len(failed) <= 20 else "\n  ... and %d more" % (len(failed) - 20)
            self.fail("%d of the checks in %s failed:\n  %s%s" % (len(failed), fn.__name__, shown, more))


def get_function_source(name, start_hint=None):
    """Exact source of one top-level function of retro_tv_emulator.py, found with the real AST."""
    lines = MAIN_SRC.splitlines(keepends=True)
    candidates = [n for n in MAIN_TREE.body if isinstance(n, ast.FunctionDef) and n.name == name]
    if not candidates:
        raise LookupError("function %r not found at module level in %s" % (name, MAIN_SCRIPT))
    if len(candidates) > 1 and start_hint is not None:
        candidates.sort(key=lambda n: abs(n.lineno - start_hint))
    node = candidates[0]
    return "".join(lines[node.lineno - 1:node.end_lineno])


def load_function(name, namespace=None, start_hint=None):
    """Execs the extracted function into a fresh namespace (seeded with `namespace`, e.g. a stub `log`) and returns it."""
    ns = dict(namespace or {})
    exec(compile(get_function_source(name, start_hint=start_hint), filename="<extracted:%s>" % name, mode="exec"), ns)
    return ns[name]


