    n1_check("with Turn Off Computer showing, W from it goes back to Mono Audio", move(table, {}, "SYSTEM_ROWS", "poweroff", mn.UP), "mono_stereo_toggle")

    s1, s2 = {}, {}
    rows = system_rows(False, False)
    table = mn.system_table(rows)
