    def test_tune_in_loudness_scans_take_turns_and_drop_when_the_viewer_leaves(self):
        prime = main_function_source("_prime_channel_block_loudness")
        self.assertIn("_loudness_prime_turns.acquire(timeout=1.0)", prime)
