class TestAllSettingsTurnsOnSticksAndSyncsProfiles(unittest.TestCase):
    """Owner 2026-11-07: with All Settings on, changing the L-STICK AS D-PAD switch changes it on every console (turning All Settings on changes nothing by itself), and a profile pick goes to every console"""

    def test_all_settings_applies_a_stick_change_to_every_console(self):
        import json
        import tempfile
        import game_deck as gd
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "emulator_config.json")
            with open(path, "w", encoding="utf-8") as handle:
                json.dump({"SNES_mapping": {"stick_as_dpad": False}, "SNES_mapping_p2": {"stick_as_dpad": False}}, handle)
            deck = gd.ExternalGameDeck.__new__(gd.ExternalGameDeck)
            deck._gameplay_ctrl_mapping_cache = {"SNES": {1: object()}}
            deck.ctrl_mapping = {"stick_as_dpad": False}
            deck._active_mapping_console = "SNES"
            original = gd.resolve_emulator_config_path
            gd.resolve_emulator_config_path = lambda: path
            try:
                deck.set_stick_as_dpad_everywhere(True)
            finally:
                gd.resolve_emulator_config_path = original
            with open(path, "r", encoding="utf-8") as handle:
                saved = json.load(handle)
        for console in gd.CONSOLE_ORDER:
            if console in ("DVD", "N64"):
                self.assertNotIn(gd.ExternalGameDeck._mapping_key(console, 1), saved if console == "DVD" else {}, console)
                continue
            for player in range(1, gd.CONSOLE_MAX_PLAYERS.get(console, 4) + 1):
                self.assertTrue(saved[gd.ExternalGameDeck._mapping_key(console, player)]["stick_as_dpad"], (console, player))
        self.assertNotIn("N64_mapping", saved, "N64 has no such switch")
        self.assertTrue(saved["GBA_mapping"]["stick_as_dpad"])
        self.assertTrue(deck.ctrl_mapping["stick_as_dpad"])
        self.assertEqual(deck._gameplay_ctrl_mapping_cache, {})
        self.assertIn("game_deck.set_stick_as_dpad_everywhere(", MAIN_SRC)
        self.assertNotIn("turn_on_stick_as_dpad_everywhere", MAIN_SRC)
        _toggle = get_function_source("_toggle_all_profiles")
        self.assertNotIn("stick_as_dpad", _toggle, "switching All Settings on changes no stick switch by itself")

    def test_a_profile_pick_goes_to_every_console_while_all_settings_is_on(self):
        self.assertIn("_targets = [c for c in CONSOLE_ORDER if c != \"MENU\"] if db.config.get(\"all_profiles_sync\", False) else [con]", MAIN_SRC)
        self.assertIn("game_deck.sync_profile_from_db(_target, db.config)", MAIN_SRC)


class TestUpdateYesClosesMenusBehind(unittest.TestCase):
    """Owner 2026-11-07: Yes on the update popup closes the menus behind it and leaves the popup and load bar up"""

    def test_yes_closes_the_menu_and_the_controls_splash_but_not_the_popup(self):
        class _Ticks:
            @staticmethod
            def get_ticks():
                return 1234
        class _Pg:
            time = _Ticks
        class _Thread:
            def __init__(self, *a, **k):
                pass
            def start(self):
                pass
        class _Thr:
            Thread = _Thread
        class _Log:
            @staticmethod
            def info(*a, **k):
                pass
        state = {"show_menu": True, "show_splash": True, "show_clear_confirm": True, "clear_confirm_target": "app_update", "menu_layer": "SYSTEM_ADVANCED_SUB_MENU",
                 "_update_record": {"version": "9.9.9"}, "games_tab_page": 2, "controls_splash_page": 3}
        ns = {"app_state": state, "pygame": _Pg, "threading": _Thr, "log": _Log, "auto_updater": None, "_update_base_dir": lambda: ".",
              "UPDATE_INSTALL_DOWNLOAD_CAP": 0.80}
        exec(main_function_code("_close_menus_behind_update_popup"), ns)
        exec(main_function_code("_begin_update_install"), ns)
        self.assertTrue(ns["_begin_update_install"]())
        self.assertFalse(state["show_menu"])
        self.assertFalse(state["show_splash"])
        self.assertEqual(state["menu_layer"], "TAB_SELECTION")
        self.assertTrue(state["show_clear_confirm"], "the Yes/No popup stays up")
        self.assertEqual(state["clear_confirm_target"], "app_update")
        self.assertTrue(state["update_install_active"], "the load bar is on")
        blocked = {"show_menu": True, "show_splash": True, "_update_record": None}
        ns["app_state"] = blocked
        self.assertFalse(ns["_begin_update_install"]())
        self.assertTrue(blocked["show_menu"], "with no update package nothing is closed")


